const body = $input.first().json.body;

const entry = body?.entry?.[0];
const change = entry?.changes?.[0]?.value;

if (!change || !Array.isArray(change.messages) || change.messages.length === 0) {
  return [{ json: { skip: true, emailHtml: '', senderName: '', senderPhone: '', messageText: '', timestamp: '' } }];
}

const message = change.messages[0];
const contact = change.contacts?.[0];

const senderName  = contact?.profile?.name || 'Unknown Sender';
const senderPhone = message.from || '';
const messageType = message.type || 'text';
const messageText = message.text?.body || `[${messageType} message — cannot display inline]`;
const timestamp   = new Date(parseInt(message.timestamp) * 1000).toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });

const emailHtml = `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/></head><body style="margin:0;padding:0;font-family:Arial,sans-serif;background:#f4f4f4;"><div style="max-width:600px;margin:32px auto;background:#fff;border-radius:10px;overflow:hidden;box-shadow:0 2px 16px rgba(0,0,0,0.10);"><div style="background:#1a1a2e;padding:24px 32px;"><img src="https://yellowfeather.netlify.app/logo-landscape.png" alt="Yellow Feather Books" style="height:44px;object-fit:contain;"/></div><div style="padding:32px;"><h2 style="color:#1a1a2e;margin-top:0;font-size:20px;">WhatsApp Reply Received</h2><table style="width:100%;border-collapse:collapse;margin-bottom:24px;font-size:14px;"><tr style="background:#f9f9f9;"><td style="padding:10px 14px;font-weight:bold;color:#555;width:90px;">From</td><td style="padding:10px 14px;color:#1a1a2e;">${senderName}</td></tr><tr><td style="padding:10px 14px;font-weight:bold;color:#555;">Phone</td><td style="padding:10px 14px;color:#1a1a2e;">+${senderPhone}</td></tr><tr style="background:#f9f9f9;"><td style="padding:10px 14px;font-weight:bold;color:#555;">Time</td><td style="padding:10px 14px;color:#1a1a2e;">${timestamp}</td></tr></table><div style="background:#f5f0e8;border-left:4px solid #C9922A;padding:16px 20px;border-radius:4px;margin-bottom:28px;"><p style="margin:0;font-size:15px;color:#1a1a2e;line-height:1.7;">${messageText}</p></div><a href="https://wa.me/${senderPhone}" style="display:inline-block;background:#25D366;color:#fff;padding:12px 24px;border-radius:6px;text-decoration:none;font-size:14px;font-weight:bold;">&#128172; Reply on WhatsApp</a></div><div style="background:#f5f0e8;padding:16px 32px;font-size:12px;color:#888;border-top:1px solid #e5e0d8;">Yellow Feather Books &mdash; Automated WhatsApp Reply Notification</div></div></body></html>`;

return [{ json: { senderName, senderPhone, messageText, messageType, timestamp, emailHtml } }];
